def next_action(response):
    """Decide what the agent loop does after one API response."""
    reason = response.stop_reason
    if reason == "end_turn":
        return "done"
    if reason == "tool_use":
        return "run_tools"
    if reason == "pause_turn":
        return "resume"        # re-send user + assistant content, no extra message
    if reason == "max_tokens":
        return "retry_bigger"  # tool input may be cut off: never run it
    return "stop"              # refusal or anything unknown: run nothing

import anthropic
from anthropic import beta_tool

client = anthropic.Anthropic()
ORDERS = {"TN-1042": "shipped to Sfax", "TN-2077": "preparing in Tunis"}


@beta_tool
def lookup_order(order_id: str) -> str:
    """Get the status of one order. Call this whenever the customer mentions an order id.

    Args:
        order_id: Order id such as TN-1042.
    """
    return ORDERS.get(order_id, f"Error: no order with id {order_id}. Ask the customer to check it.")


runner = client.beta.messages.tool_runner(
    model="claude-opus-5-5",
    max_tokens=16000,
    tools=[lookup_order],
    messages=[{"role": "user", "content": "Win wsolt TN-1042 w TN-2077?"}],
)
last = None
for turn, message in enumerate(runner, start=1):
    last = message
    if turn >= 10:  # turn budget
        break
if last is not None and last.stop_reason == "end_turn":
    print("".join(b.text for b in last.content if b.type == "text"))
else:
    print("stopped:", last.stop_reason if last else "no answer")

